#include "HardwareBenchRuntime.h"
namespace dnxr {
HardwareBenchRuntimeResult HardwareBenchRuntime::startDryRun(RealNeuralChipHAL& hal,const HardwareBenchSessionManifest& m){ std::string reason; if(!HardwareBenchSession::isAccepted(m,&reason)) return {false,true,false,reason}; auto st=HardwareBenchSelfTest{}.runDryRunSelfTest(); RealReadinessEvidence e; e.deploymentMode=m.deploymentMode; e.hardwareSelfTestPassed=st.passed(); e.safetyKernelOnline=m.safetyKernelEnabled; e.emergencyStopReady=m.emergencyStopVerified; e.traceRecorderOnline=m.traceRecordingEnabled; e.qmsSignatureValid=true; e.targetType=m.targetType; e.activeStimulationRequested=false; auto d=RealReadinessGate{}.evaluate(e); if(!d.allowed) return {false,true,false,d.reason}; hal.init("hardware_bench_dry_run"); hal.handshake(); hal.selfTest(); hal.getCapabilities(); return {true,true,false,"hardware_bench_dry_run_started_no_active_output"}; }
HardwareBenchRuntimeResult HardwareBenchRuntime::sendActiveToDummyLoad(RealNeuralChipHAL& hal,const HardwareBenchSessionManifest& m,const DummyLoadAdapter& dl,const BoundedStimulusCommand& c){ if(!dl.attached()) return {false,false,false,"dummy_load_required"}; auto r=startDryRun(hal,m); if(!r.started) return r; if(!m.activeStimulationEnabled) return {false,false,false,"active_stimulation_disabled_by_manifest"}; auto cmd=c; cmd.dummyLoadAttached=true; bool sent=hal.sendBoundedFrame(cmd); return {sent,false,sent,sent?"active_output_sent_to_dummy_load":"hal_rejected_bounded_frame"}; }
}
